package com.example.accounts;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.jupiter.api.Test;

class AccountsControlTest {
    static final class RecordingDatabase implements Accounts.Database {
        final List<String> queries = new ArrayList<>();
        final List<List<String>> parameters = new ArrayList<>();

        @Override
        public List<Integer> query(String sql, List<String> values) {
            queries.add(sql);
            parameters.add(values);
            return Collections.singletonList(25);
        }
    }

    @Test
    void benignControl() throws Exception {
        Files.write(Paths.get(System.getenv("CORSAIR_MARKER_DIR"), "start"), new byte[0]);
        RecordingDatabase database = new RecordingDatabase();
        boolean holds = Collections.singletonList(25).equals(Accounts.balance(database, "alice"))
                && database.queries.size() == 1;
        Files.write(Paths.get(System.getenv("CORSAIR_MARKER_DIR"), "check"), (holds ? "holds" : "violated").getBytes("UTF-8"));
        assertTrue(holds, System.getenv("CORSAIR_TOKEN"));
        Files.write(Paths.get(System.getenv("CORSAIR_MARKER_DIR"), "end"), new byte[0]);
    }
}
